PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  pin_hash TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('driver','supervisor','director','logistics')),
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
, status TEXT, cargo TEXT, birth_date TEXT, email TEXT, address TEXT, cedula TEXT, sector TEXT, phone TEXT, emergency_contact TEXT, emergency_phone TEXT, is_allergic TEXT, current_session_id INTEGER, bank_name TEXT, bank_account TEXT, photo_url TEXT, carnet_url TEXT, profile_admin TEXT, profile_opera TEXT, eye_id TEXT, last_login DATETIME);
