CREATE TABLE vehicles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  plate TEXT NOT NULL,
  brand TEXT,
  model TEXT,
  color TEXT,
  status TEXT NOT NULL CHECK(status IN ('pre-registered','checkin','parked','requested','delivering','delivered','pending_retrieval','retrieved')),
  ticket_code TEXT UNIQUE,
  owner_name TEXT,
  owner_phone TEXT,
  owner_id_ref TEXT,
  parking_spot TEXT,
  damage_notes TEXT,
  fee_amount REAL,
  fee_paid INTEGER DEFAULT 0,
  payment_method TEXT,
  valet_in TEXT,
  valet_out TEXT,
  check_in_at TEXT DEFAULT CURRENT_TIMESTAMP,
  check_out_at TEXT,
  session_id INTEGER,
  daily_seq INTEGER,
  retrieval_token TEXT,
  auth_token_1 TEXT,
  auth_token_2 TEXT,
  conformity_signed INTEGER DEFAULT 0,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP, vehicle_type TEXT DEFAULT 'car',
  FOREIGN KEY(session_id) REFERENCES sessions(id)
);
