CREATE TABLE events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  vehicle_id INTEGER NOT NULL,
  user_id INTEGER NOT NULL,
  event_type TEXT NOT NULL CHECK(event_type IN ('checkin','parked','requested','delivering','delivered')),
  key_hook TEXT,
  slot_id INTEGER,
  ts TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
);
INSERT INTO "events" VALUES(1,1000,89,'checkin',NULL,NULL,'2026-04-25 20:03:16');
INSERT INTO "events" VALUES(2,1001,89,'checkin',NULL,NULL,'2026-04-25 20:03:16');
CREATE TABLE photos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  vehicle_id INTEGER NOT NULL,
  url TEXT NOT NULL,
  FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE slots (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  zone TEXT NOT NULL,
  number INTEGER NOT NULL,
  is_free INTEGER DEFAULT 1
);
CREATE TABLE messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  vehicle_id INTEGER NOT NULL,
  from_role TEXT NOT NULL,
  to_role TEXT NOT NULL,
  text TEXT NOT NULL,
  ts TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE metrics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  vehicle_id INTEGER NOT NULL,
  avg_time INTEGER,
  alerts_count INTEGER DEFAULT 0,
  FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)
);
CREATE TABLE reservations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  confirm_code TEXT NOT NULL UNIQUE,
  owner_name TEXT NOT NULL,
  owner_phone TEXT NOT NULL,
  plate TEXT,
  brand TEXT,
  model TEXT,
  expected_arrival TEXT NOT NULL,
  notes TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'arrived', 'cancelled')),
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE sessions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  status TEXT DEFAULT 'planning' CHECK(status IN ('planning', 'active', 'closed')),
  started_at TEXT DEFAULT CURRENT_TIMESTAMP,
  ended_at TEXT
, event_end_date TEXT);
INSERT INTO "sessions" VALUES(100,'CUMPLEAÑOS 50 ANIVERSARIO','closed','2026-04-24 20:00:00','2026-04-25 02:00:00',NULL);
