CREATE TABLE payroll_rates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  role TEXT NOT NULL UNIQUE,
  rate REAL NOT NULL,
  description TEXT
);
INSERT INTO "payroll_rates" VALUES(1,'driver',50,'Pago base por turno de conductor');
