CREATE TABLE payroll_submissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  session_id INTEGER NOT NULL,
  date TEXT NOT NULL,
  role_at_event TEXT NOT NULL,
  bank_name TEXT,
  bank_account TEXT,
  amount REAL,
  status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected')),
  approved_at TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(user_id) REFERENCES users(id),
  FOREIGN KEY(session_id) REFERENCES sessions(id)
);
CREATE TABLE equivalences (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  category TEXT NOT NULL CHECK(category IN ('brand', 'model', 'color')),
  original_value TEXT NOT NULL,
  standard_value TEXT NOT NULL,
  UNIQUE(category, original_value)
);
INSERT INTO "equivalences" VALUES(1,'brand','TOYO','TOYOTA');
INSERT INTO "equivalences" VALUES(2,'brand','TOYOT','TOYOTA');
INSERT INTO "equivalences" VALUES(3,'brand','FORDD','FORD');
