CREATE TABLE assets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK(type IN ('equipment', 'vehicle', 'other')),
  status TEXT DEFAULT 'available',
  description TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE locations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  entity_id INTEGER NOT NULL,
  entity_type TEXT NOT NULL CHECK(entity_type IN ('staff', 'asset')),
  latitude REAL NOT NULL,
  longitude REAL NOT NULL,
  accuracy REAL,
  ts TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE staff_attendance (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      session_id INTEGER,
      type TEXT, -- 'entry', 'exit', 'break_start', 'break_end'
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE access_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, visitor_name TEXT, visitor_id_ref TEXT, visitor_email TEXT, visitor_phone TEXT, visitor_type TEXT NOT NULL DEFAULT 'regular', company_name TEXT, vehicle_details TEXT, activity_desc TEXT, status TEXT DEFAULT 'in', entry_at TEXT DEFAULT CURRENT_TIMESTAMP, exit_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, comments TEXT, FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE guest_list (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, name TEXT NOT NULL, id_ref TEXT, type TEXT DEFAULT 'regular', status TEXT DEFAULT 'pending', FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE geofences (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  latitude REAL NOT NULL,
  longitude REAL NOT NULL,
  radius INTEGER NOT NULL,
  type TEXT CHECK(type IN ('office', 'client', 'danger_zone')) DEFAULT 'office',
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE geofence_alerts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  geofence_id INTEGER NOT NULL,
  alert_type TEXT CHECK(alert_type IN ('entry', 'exit')),
  ts TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(user_id) REFERENCES users(id),
  FOREIGN KEY(geofence_id) REFERENCES geofences(id)
);
CREATE TABLE social_metrics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  platform TEXT NOT NULL, 
  followers INTEGER,
  following INTEGER,
  posts_count INTEGER,
  avg_engagement REAL,
  date TEXT DEFAULT (date('now')),
  UNIQUE(platform, date)
);
