INSERT INTO "social_metrics" VALUES(2,'instagram',1929,NULL,NULL,NULL,'2026-04-27');
CREATE TABLE social_content (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  platform TEXT NOT NULL,
  post_id TEXT,
  type TEXT, 
  content_text TEXT,
  media_url TEXT,
  likes INTEGER,
  comments_count INTEGER,
  sentiment_score REAL, 
  perceived_message TEXT,
  published_at TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO "social_content" VALUES(1,'tiktok','https://www.tiktok.com/@grupoeyestaff/video/7632358947017461013',NULL,replace('<p>¡Misión cumplida en Las Mercedes! 🌆✨ La logística no es solo coordinar piezas, es confiar plenamente en el que tienes al lado. En la 2da Carrera Match and Run, volvimos a demostrar que cuando trabajamos con un solo objetivo, el resultado es impecable. Orgullosos de este equipo que lo da todo, desde el montaje hasta el último corredor en meta. 🤜🤛 #grupoeyestaff </p>\n<a href="https://www.tiktok.com/@grupoeyestaff/video/7632358947017461013"><img src="https://p16-common-sign.tiktokcdn-eu.com/tos-alisg-p-0037/oIr9Bf03CinqIhlG5C0wiARrIzIcAl2WXA47RC~tplv-tiktokx-origin.image?dr=10395&x-expires=1777438800&x-signature=IWNCYHsatL3%2BgTT02QIimNRONYg%3D&t=4d5b0474&ps=13740610&shp=81f88b70&shcp=43f4a2f9&idc=useast2b"/></a>\n<p>835 views<p><br/>','\n',char(10)),NULL,NULL,NULL,0.8,'Excelente contenido que muestra la satisfacción del cliente y la efectividad de la logística en un evento. El equipo se presenta como unido y comprometido con el objetivo, lo que genera una conexión emocional con los seguidores. El contenido es atractivo y fácil de compartir.','2026-04-27T05:39:43.032Z','2026-04-27 05:40:00');
INSERT INTO "social_content" VALUES(2,'tiktok','https://www.tiktok.com/@grupoeyestaff/video/7631007712322587925',NULL,replace('<p></p>\n<a href="https://www.tiktok.com/@grupoeyestaff/video/7631007712322587925"><img src="https://p16-common-sign.tiktokcdn-eu.com/tos-alisg-p-0037/ooImipi9ESQsAFHTOJcQxgBy7Yf5BKD9EQTfRX~tplv-tiktokx-origin.image?dr=10395&x-expires=1777438800&x-signature=Ond6cAVhYEvM2T%2F%2BUoKIvi8bmSU%3D&t=4d5b0474&ps=13740610&shp=81f88b70&shcp=43f4a2f9&idc=useast2b"/></a>\n<p>571 views<p><br/>','\n',char(10)),NULL,NULL,NULL,0,'No analizado','2026-04-27T05:40:00.398Z','2026-04-27 05:40:15');
INSERT INTO "social_content" VALUES(3,'tiktok','https://www.tiktok.com/@grupoeyestaff/video/7629752211140283668',NULL,replace('<p>¿Sabías que el Control de Acceso es el corazón de cualquier evento? 🛡️ A menudo es el servicio más subestimado, pero es el primer punto de contacto y la clave para garantizar la seguridad de tus invitados.  Desde una boda íntima hasta un concierto masivo, en Eye Staff nos encargamos de que el ingreso sea fluido, seguro y profesional. #grupoeyestaff #controldeacceso #eventos</p>\n<a href="https://www.tiktok.com/@grupoeyestaff/video/7629752211140283668"><img src="https://p16-common-sign.tiktokcdn-eu.com/tos-alisg-p-0037/osfpNkRDE6D4EitE8UFMBQrzBkeOQgB5lBBUjA~tplv-tiktokx-origin.image?dr=10395&x-expires=1777438800&x-signature=C7jGWJidj%2BDTk4u4gjZLC4QslsM%3D&t=4d5b0474&ps=13740610&shp=81f88b70&shcp=43f4a2f9&idc=useast2b"/></a>\n<p>725 views<p><br/>','\n',char(10)),NULL,NULL,NULL,0,'No analizado','2026-04-27T05:40:15.871Z','2026-04-27 05:40:34');
INSERT INTO "social_content" VALUES(4,'tiktok','https://www.tiktok.com/@grupoeyestaff/video/7625797694975577365',NULL,replace('<p>Nos trasladamos a MARGARITA y estuvimos en el SACA PECHO FEST #GrupoEyeStaff #sacaelPechoFest #ss2026</p>\n<a href="https://www.tiktok.com/@grupoeyestaff/video/7625797694975577365"><img src="https://p16-common-sign.tiktokcdn-eu.com/tos-alisg-p-0037/os0vIUZCABidOwpA9RqAfiqwNAuzCILIIi6nyC~tplv-tiktokx-origin.image?dr=10395&x-expires=1777438800&x-signature=g19CjVusTK6Z%2Bg0wzh2z81qFXqw%3D&t=4d5b0474&ps=13740610&shp=81f88b70&shcp=43f4a2f9&idc=useast2b"/></a>\n<p>1519 views<p><br/>','\n',char(10)),NULL,NULL,NULL,0,'No analizado','2026-04-27T05:40:34.706Z','2026-04-27 05:40:53');
INSERT INTO "social_content" VALUES(5,'tiktok','https://www.tiktok.com/@grupoeyestaff/video/7621278437071785237',NULL,replace('<p>Ayer en Caracas, la meta era correr; la nuestra, que todo saliera perfecto. 🏁🛡️ Desde el montaje inicial hasta el último corredor que cruzó el arco, Grupo Eye Staff estuvo presente en cada paso de Farmatodo Corre. No solo somos seguridad, somos logística, orden y el respaldo que permite que grandes eventos como este sean posibles en nuestra ciudad. 🧤✨ ¿Nos viste en la ruta? Cuéntanos tu experiencia ayer. 👇 #FarmatodoCorre #GrupoEyeStaff #SeguridadLogistica #CaracasCorre #EventosCaracas </p>\n<a href="https://www.tiktok.com/@grupoeyestaff/video/7621278437071785237"><img src="https://p16-common-sign.tiktokcdn-eu.com/tos-alisg-p-0037/o0HERCAAgfYAIg9sboLEfOO7yeeMNiOfBAGG4H~tplv-tiktokx-origin.image?dr=10395&x-expires=1777438800&x-signature=0Ne5qq4fUKjZ9K2w2PNDG0%2BSREI%3D&t=4d5b0474&ps=13740610&shp=81f88b70&shcp=43f4a2f9&idc=useast2b"/></a>\n<p>775 views<p><br/>','\n',char(10)),NULL,NULL,NULL,0,'No analizado','2026-04-27T05:40:53.744Z','2026-04-27 05:41:10');
INSERT INTO "social_content" VALUES(6,'instagram','https://www.instagram.com/p/DXiHaL7BYA5/',NULL,replace('<video controls><source src="https://scontent.cdninstagram.com/o1/v/t2/f2/m86/AQOZ5nl827ig5MynzCQEUq3qBmB4Wx4nZoeZYixaIjcuFTlFk_pnIg-pWEO5oavxaWmoPuC-1UxkhzDc6B11g097Tb78ey4L96evUis.mp4?_nc_cat=109&_nc_sid=5e9851&_nc_ht=scontent.cdninstagram.com&_nc_ohc=rT5EeP83m00Q7kNvwHkSK0O&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTg1ODU0ODcwOTkwNDM4MTAsImFzc2V0X2FnZV9kYXlzIjoyLCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6NDcsInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=2b9ee22c107ffe63&_nc__6DI3dmDQhUCKAJDMywXQEfZmZmZmZoYEmRhc2hfYmFzZWxpbmVfMV92MREAdf4HZeadAQA&_nc_gid=cHmOh_1Do5_R-8sntr7SeA&_nc_ss=7a22e&_nc_zt=28&oh=00_Af2VB9skOeWtDmorAs2PEDDnv8FPcbnrWq1iUCaDmFdxrw&oe=69F0D166" poster="https://www.instagram.com/p/DXiHaL7BYA5/media?size=l" type="video/mp4"><img src="https://www.instagram.com/p/DXiHaL7BYA5/media?size=l" alt=""></video><br><br>&iexcl;Misi&oacute;n cumplida en Las Mercedes! 🌆✨<br />\nLa log&iacute;stica no es solo coordinar piezas, es confiar plenamente en el que tienes al lado. En la 2da Carrera Match and Run, volvimos a demostrar que cuando trabajamos con un solo objetivo, el resultado es impecable.<br />\nOrgullosos de este equipo que lo da todo, desde el montaje hasta el &uacute;ltimo corredor en meta. 🤜🤛<br />\n<br />\n#grupoeyestaff #matchandRun #hipereventos #polarlight','\n',char(10)),NULL,NULL,NULL,0.75,'El contenido es atractivo y muestra la misión cumplida de EYE STAFF en la Carrera Match and Run. La inclusión de emojis y la narrativa positiva sobre el equipo y su trabajo crea una percepción positiva y orgullosa. Sin embargo, la publicación podría beneficiarse de un llamado a la acción o un enlace a más información sobre el evento o la empresa.','2026-04-27T05:41:11.056Z','2026-04-27 05:41:29');
INSERT INTO "social_content" VALUES(7,'instagram','https://www.instagram.com/p/DXfmvi6CRko/',NULL,replace('<a href="https://www.instagram.com/p/DXfmvi6CRko/" target="_blank"><img src="https://www.instagram.com/p/DXfmvi6CRko/media?size=l" alt="Detrás de cada gran meta, hay un equipo que lo hace posible. 🏁..." /></a><br><br>Detr&aacute;s de cada gran meta, hay un equipo que lo hace posible. 🏁<br />\nAyer vivimos la adrenalina de la 2da Carrera Match and Run en Las Mercedes, donde nuestro <a href="https://www.instagram.com/explore/tags/TeamEyeStaff">#TeamEyeStaff</a> demostr&oacute; que la log&iacute;stica es el coraz&oacute;n de los grandes eventos. No solo montamos estructuras, construimos experiencias impecables a trav&eacute;s del trabajo en equipo y la precisi&oacute;n.<br />\n&iexcl;Seguimos sumando kil&oacute;metros de &eacute;xito! 🚀💨<br />\n<br />\n<a href="https://www.instagram.com/explore/tags/MatchAndRun">#MatchAndRun</a> <a href="https://www.instagram.com/explore/tags/LogisticaDeEventos">#LogisticaDeEventos</a> <a href="https://www.instagram.com/explore/tags/LasMercedes">#LasMercedes</a> <a href="https://www.instagram.com/explore/tags/teamEyeStaff">#teamEyeStaff</a>','\n',char(10)),NULL,NULL,NULL,0.8,'La publicación destaca la importancia del equipo y la logística en el éxito de los eventos, transmitiendo un tono positivo y emocionante.','2026-04-27T05:41:29.692Z','2026-04-27 05:41:47');
