INSERT INTO "social_content" VALUES(9,'instagram','https://www.instagram.com/p/DXaUXskBubL/',NULL,replace('<video controls><source src="https://scontent.cdninstagram.com/o1/v/t2/f2/m86/AQO4z-M9kOgUlfkEWz7wmAkFLLxoS7mZdqNKgEEzeNgUc9zEfdD1ey6rfJB47HunnRCrgRg7wdekMq1VAjLGj8hJwibLNqQNCopImXw.mp4?_nc_cat=109&_nc_sid=5e9851&_nc_ht=scontent.cdninstagram.com&_nc_ohc=EvjiUTsG7wkQ7kNvwFGx2Rl&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTg1ODQ3NDEyMjEwNDM4MTAsImFzc2V0X2FnZV9kYXlzIjo1LCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6NDIsInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=ad607471642d19be&_nc_&_nc_gid=cHmOh_1Do5_R-8sntr7SeA&_nc_zt=28&_nc_ss=7a22e&oh=00_Af097Ghbvi2JBAARhKAkbDUHFD83jI5hICgzeA6G-hFfsg&oe=69F0BF4E" poster="https://www.instagram.com/p/DXaUXskBubL/media?size=l" type="video/mp4"><img src="https://www.instagram.com/p/DXaUXskBubL/media?size=l" alt=""></video><br><br>Log&iacute;stica de alto nivel en el para&iacute;so. 🌴📍 Los Caracas fue el escenario de la carrera La Perla y en Eye Staff nos activamos con el control y la seguridad para Polar Light.<br />\n&iexcl;Donde hay grandes marcas, ah&iacute; estamos nosotros! 👊🛡️<br />\n<br />\n#GrupoEyeStaff #PolarLight #LaPerla2026 #LosCaracas #LogisticaDeEventos','\n',char(10)),NULL,NULL,NULL,0.7,'The post showcases Eye Staff''s expertise in logistics and security for high-level events, highlighting their presence at the La Perla race in Los Caracas. The use of hashtags and emojis adds a playful and engaging tone, but the post could benefit from more specific details about the event and the services provided by Eye Staff. Overall, the post effectively communicates the company''s capabilities and presence in the industry, but could be more effective in grabbing the attention of potential clients.','2026-04-27T05:41:47.375Z','2026-04-27 05:42:03');
INSERT INTO "social_content" VALUES(10,'instagram','https://www.instagram.com/p/DXX0JtbCUT3/',NULL,replace('<video controls><source src="https://scontent.cdninstagram.com/o1/v/t2/f2/m86/AQNa8ZChUnwl1L7JQy_QNBSXoEECQceT-0vkY3rkGTZ_i_q5GA-p6TW815gEg77cBhnGi5n8WZOJmYbAoQ1hOAFlCBzy7cCznxBkT14.mp4?_nc_cat=105&_nc_sid=5e9851&_nc_ht=scontent.cdninstagram.com&_nc_ohc=9LLR-OYIYh4Q7kNvwFKFD54&efg=eyJ2ZW5jb2RlX3RhZyI6Inhwdl9wcm9ncmVzc2l2ZS5JTlNUQUdSQU0uQ0xJUFMuQzMuNzIwLmRhc2hfYmFzZWxpbmVfMV92MSIsInhwdl9hc3NldF9pZCI6MTg1ODQ1NjY4OTcwNDM4MTAsImFzc2V0X2FnZV9kYXlzIjo2LCJ2aV91c2VjYXNlX2lkIjoxMDA5OSwiZHVyYXRpb25fcyI6NjEsInVybGdlbl9zb3VyY2UiOiJ3d3cifQ%3D%3D&ccb=17-1&vs=b98ed1d12e07ff2c&_nc__DlaSDQhUCKAJDMywXQE77peNT988YEmRhc2hfYmFzZWxpbmVfMV92MREAdf4HZeadAQA&_nc_gid=cHmOh_1Do5_R-8sntr7SeA&_nc_ss=7a22e&_nc_zt=28&oh=00_Af0onYwRnODawkzN8L8K4QiDnBVHzw0PveeVIxrt19guKQ&oe=69F0D4E2" poster="https://www.instagram.com/p/DXX0JtbCUT3/media?size=l" type="video/mp4"><img src="https://www.instagram.com/p/DXX0JtbCUT3/media?size=l" alt=""></video><br><br>Tuvimos el placer de estar en el S&Aacute;BADO FAMILIAR DEL INSTITUTO ANDES DE CARACAS.<br />\n<br />\n  Una vez m&aacute;s brindamos todo nuestro apoyo en el control de acceso y log&iacute;stica.<br />\n<br />\n@iandescaracas <br />\n#grupoeyestaff #eventos #teameyestaff #eventosvzla','\n',char(10)),NULL,NULL,NULL,0,'No analizado','2026-04-27T05:42:03.595Z','2026-04-27 05:42:21');
CREATE TABLE social_insights (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT,
  content TEXT,
  category TEXT, 
  date TEXT DEFAULT (date('now'))
);
CREATE TABLE audit_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER,
      action TEXT,
      details TEXT,
      ip TEXT,
      device TEXT,
      timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE valet_clients (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT, email TEXT, event_type TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE budgets (
  id TEXT PRIMARY KEY,
  empresa TEXT,
  evento TEXT,
  fecha TEXT,
  monto TEXT,
  estatus TEXT DEFAULT 'GENERADO',
  action TEXT,
  form_data TEXT, 
  items_data TEXT, 
  timestamp INTEGER,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE budget_seq (
  year INTEGER PRIMARY KEY,
  seq INTEGER DEFAULT 0
);
CREATE TABLE job_applications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  cedula TEXT NOT NULL,
  email TEXT,
  phone TEXT,
  address TEXT,
  birth_date TEXT,
  experience TEXT,
  photo_url TEXT,
  status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'interviewed', 'hired', 'rejected')),
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE rentals (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  budget_id TEXT NOT NULL UNIQUE,
  status TEXT DEFAULT 'planning' CHECK(status IN ('planning', 'delivering', 'delivered', 'retrieving', 'completed')),
  delivery_photos TEXT,
  retrieval_photos TEXT,
  delivery_signature TEXT,
  retrieval_signature TEXT,
  notes TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(budget_id) REFERENCES budgets(id)
);
CREATE TABLE access_control_guests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  session_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  qr_code_id TEXT UNIQUE NOT NULL,
  status TEXT DEFAULT 'PENDING' CHECK(status IN ('PENDING', 'CHECKED_IN')),
  guest_type TEXT DEFAULT 'INVITADO', 
  phone TEXT,
  email TEXT,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  checked_in_at TEXT,
  FOREIGN KEY(session_id) REFERENCES sessions(id)
);
